<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Bootstrap\Management\Log;

const GZGETS_OVERRIDE_FLAG = '__test_force_gzgets_false';

function gzopen(string $file, string $mode)
{
    return \gzopen($file, $mode);
}

function gzeof($h): bool
{
    if (!empty($GLOBALS[GZGETS_OVERRIDE_FLAG])) {
        return false;
    }
    return \gzeof($h);
}

function gzgets($h)
{
    if (!empty($GLOBALS[GZGETS_OVERRIDE_FLAG])) {
        return false;
    }
    return \gzgets($h);
}

function gzclose($h): void
{
    \gzclose($h);
}


const GLOB_OVERRIDE_FLAG = '__test_force_glob_false';

function glob(string $pattern, int $flags = 0): array|false
{
    if (!empty($GLOBALS[GLOB_OVERRIDE_FLAG])) {
        return false;
    }
    return \glob($pattern, $flags);
}
